256	    @Override
257	    @Transactional
258	    public void saveOwner(Owner owner) throws DataAccessException {
259	        boolean isNew = owner.isNew();
260	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
261	        // roll it forward to the next business day so it never lands on a weekend. Everything
262	        // derived from the registration date below must use this adjusted value.
263	        LocalDate registrationDate = toBusinessDay(
264	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
265	        owner.setRegistrationDate(registrationDate);
266	        // Whether this owner is joining an existing household (shares a last name and postcode with
267	        // owners already on file). Such a member is a legitimate household join, not a suspected
268	        // duplicate, so it is deliberately not soft-flagged below.
269	        boolean joiningExistingHousehold = false;
270	        if (owner.isNew()) {
271	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
272	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
273	            // it automatically. It is part of the owner's identityKey, so it is resolved first.
274	            owner.setHouseholdId(computeHouseholdId(owner));
275	            // The household is keyed on (last name, postcode), so the members are the existing owners
276	            // sharing both with this owner.
277	            List<Owner> householdMembers = findHouseholdMembers(owner);
278	            // Size of the household after this create: the existing members plus this new owner.
279	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
280	            // A new owner joining an existing household is accepted as a household member; it is not a
281	            // suspected duplicate. Rather than being rejected, its derived membershipLevel is capped at
282	            // one above the current maximum membershipLevel among its household members, so a new member
283	            // can never leap more than one level past the household. With no existing member no cap
284	            // applies.
285	            if (!householdMembers.isEmpty()) {
286	                joiningExistingHousehold = true;
287	                int maxLevel = householdMembers.stream()
288	                    .mapToInt(Owner::getMembershipLevel)
289	                    .max()
290	                    .getAsInt();
291	                owner.setMembershipLevelCap(maxLevel + 1);
292	            }
293	        }
294	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
295	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
296	        // subsumes the former separate telephone, email and household checks.
297	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
298	            throw new DuplicateIdentityException(owner.getIdentityKey());
299	        }
300	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
301	        // postcode while carrying a different telephone. Still created, but flagged as a possible
302	        // duplicate pointing at the matching owner. An owner joining an existing household is not a
303	        // suspected duplicate, so it is never flagged.
304	        if (owner.isNew() && !joiningExistingHousehold) {
305	            Owner softMatch = findPossibleDuplicate(owner);
306	            if (softMatch != null) {
307	                owner.setPossibleDuplicate(true);
308	                owner.setPossibleDuplicateOf(softMatch.getId());
309	            }
310	        }
311	        if (owner.isNew()
312	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
313	            throw new CityOwnerLimitExceededException(owner.getCity());
314	        }
315	        if (owner.isNew()
316	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
317	            throw new DailyOwnerLimitExceededException(registrationDate);
318	        }
319	        if (owner.isNew() && owner.getCustomerCode() == null) {
320	            owner.setCustomerCode(generateCustomerCode(owner));
321	        }
322	        if (owner.isNew()) {
323	            owner.setNamesakeCount(countNamesakes(owner));
324	            owner.setBulkSignupWarning(
325	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
326	        }
327	        if (owner.getMembershipNumber() == null) {
328	            owner.setMembershipNumber(generateMembershipNumber(owner));
329	        }
330	        ownerRepository.save(owner);
331	        if (isNew) {
332	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
333	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
334	                owner.getMembershipNumber(), owner.getRegistrationDate());
335	        }
336	    }
337	
338	    /**
339	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
340	     * owner. The key consolidates telephone, email and household into one value, so two owners
341	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
342	     * the owner's {@code householdId} has been resolved, so its key is complete.
343	     */
344	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
345	        String identityKey = owner.getIdentityKey();
346	        return ownerRepository.findAll().stream()
347	            .filter(existing -> !existing.isDeleted())
348	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
349	    }
350	
351	    /**
352	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
353	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
354	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
355	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
356	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
357	     */
358	    private Owner findPossibleDuplicate(Owner owner) {
359	        String key = householdKey(owner);
360	        if (key == null) {
361	            return null;
362	        }
363	        String telephone = owner.getTelephone();
364	        return ownerRepository.findAll().stream()
365	            .filter(existing -> !existing.isDeleted())
366	            .filter(existing -> key.equals(householdKey(existing))
367	                && !Objects.equals(telephone, existing.getTelephone()))
368	            .min(Comparator.comparing(Owner::getId))
369	            .orElse(null);
370	    }
371	
372	    /**
373	     * Count the owners that already exist (before this create) sharing the same first name and last
374	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
375	     * unique among the existing owners.
376	     */
377	    private int countNamesakes(Owner owner) {
378	        String firstName = owner.getFirstName();
379	        String lastName = owner.getLastName();
380	        if (firstName == null || lastName == null) {
381	            return 0;
382	        }
383	        return (int) ownerRepository.findAll().stream()
384	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
385	                && lastName.equalsIgnoreCase(existing.getLastName()))
386	            .count();
387	    }
388	
389	    /**
390	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
391	     * last name and its postcode. Last names are compared case-insensitively with collapsed
392	     * whitespace; postcodes are compared exactly. This is the same keying used by
393	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
394	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
395	     * postcode to match on.
396	     */
397	    private List<Owner> findHouseholdMembers(Owner owner) {
398	        String key = householdKey(owner);
399	        if (key == null) {
400	            return List.of();
401	        }
402	        return ownerRepository.findAll().stream()
403	            .filter(existing -> !existing.isDeleted())
404	            .filter(existing -> key.equals(householdKey(existing)))
405	            .toList();
406	    }
407	
408	    /**
409	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
410	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
411	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
412	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
413	     * postcode, so it does not belong to a shared household.
414	     */
415	    private String computeHouseholdId(Owner owner) {
416	        String key = householdKey(owner);
417	        return key == null ? null : sha256Hex(key, 6, false);
418	    }
419	
420	    /**
421	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
422	     * that identifies a household. The last name is normalized case-insensitively with collapsed
423	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
424	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
425	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
426	     * cannot drift apart.
427	     */
428	    private String householdKey(Owner owner) {
429	        String lastName = normalizeHouseholdKey(owner.getLastName());
430	        String postcode = owner.getPostcode();
431	        if (lastName == null || postcode == null || postcode.isBlank()) {
432	            return null;
433	        }
434	        return lastName + "|" + postcode;
435	    }
436	
437	    /**
438	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
439	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
440	     */
441	    private String normalizeHouseholdKey(String value) {
442	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
443	    }
444	
445	    /**
446	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
447	     * code resolved from the owner's postcode (falling back to the owner's city, else
448	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
449	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
450	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
451	     * derived from the owner's own attributes.
452	     * <p>
453	     * When the derived code collides with an existing owner's {@code customerCode}, a
454	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes it
455	     * unique, so distinct owners always receive distinct customer codes.
456	     */
457	    private String generateCustomerCode(Owner owner) {
458	        String base = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
459	        return deduplicateCustomerCode(base);
460	    }
461	
462	    /**
463	     * Return {@code base} when no existing owner already uses it as their {@code customerCode};
464	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
465	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
466	     */
467	    private String deduplicateCustomerCode(String base) {
468	        Set<String> existing = ownerRepository.findAll().stream()
469	            .map(Owner::getCustomerCode)
470	            .filter(Objects::nonNull)
471	            .collect(Collectors.toSet());
472	        if (!existing.contains(base)) {
473	            return base;
474	        }
475	        int n = 2;
476	        while (existing.contains(base + "-" + n)) {
477	            n++;
478	        }
479	        return base + "-" + n;
480	    }
481	
482	    /**
483	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
484	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
485	     * with the owner's last name.
486	     */
487	    private String customerHash(Owner owner) {
488	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
489	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
490	        return sha256Hex(telephone + lastName, 4, true);
491	    }
492	
493	    /**
494	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
495	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
496	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
497	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
498	     * digest handling and the "SHA-256 not available" error live in one place.
499	     */
500	    private String sha256Hex(String input, int bytes, boolean upperCase) {
501	        byte[] digest;
502	        try {
503	            digest = MessageDigest.getInstance("SHA-256")
504	                .digest(input.getBytes(StandardCharsets.UTF_8));
505	        } catch (NoSuchAlgorithmException e) {
506	            throw new IllegalStateException("SHA-256 is required but not available", e);
507	        }
508	        String format = upperCase ? "%02X" : "%02x";
509	        StringBuilder hex = new StringBuilder(bytes * 2);
510	        for (int i = 0; i < bytes; i++) {
511	            hex.append(String.format(format, digest[i]));
512	        }
513	        return hex.toString();
514	    }
515	
516	    /**
517	     * Count the owners that already exist (before this create) in the same city as {@code owner},
518	     * compared case-insensitively.
519	     */
520	    private long countOwnersInCity(Owner owner) {
521	        String city = owner.getCity();
522	        return ownerRepository.findAll().stream()
523	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
524	            .count();
525	    }
526	
527	    /**
528	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
529	     * on the given {@code date}. Used to enforce the per-day create cap.
530	     */
531	    private long countOwnersRegisteredOn(LocalDate date) {
532	        return ownerRepository.findAll().stream()
533	            .filter(existing -> date.equals(existing.getRegistrationDate()))
534	            .count();
535	    }
536	
537	    /**
538	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
539	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
540	     */
541	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
542	        LocalDate.parse("2026-01-01"),
543	        LocalDate.parse("2026-01-26"),
544	        LocalDate.parse("2026-04-25"),
545	        LocalDate.parse("2026-12-25"),
546	        LocalDate.parse("2026-12-28"));
547	
548	    /**
549	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
550	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
551	     * unchanged. Registration dates are required to fall on a business day.
552	     */
553	    private LocalDate toBusinessDay(LocalDate date) {
554	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
555	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
556	            || PUBLIC_HOLIDAYS.contains(date)) {
557	            date = date.plusDays(1);
558	        }
559	        return date;
560	    }
561	
562	    /**
563	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
564	     * last two digits of the fiscal year of the owner's business-day-adjusted
565	     * {@code registrationDate} (the fiscal year starting 1 July), e.g. {@code 'NSW-1A2B3C4D-M27'}.
566	     */
567	    private String generateMembershipNumber(Owner owner) {
568	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
569	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
570	    }
