379	        boolean dbl = true;
380	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
381	            char c = this.customerCode.charAt(i);
382	            if (c < '0' || c > '9') {
383	                continue;
384	            }
385	            int d = c - '0';
386	            if (dbl) {
387	                d *= 2;
388	                if (d > 9) {
389	                    d -= 9;
390	                }
391	            }
392	            sum += d;
393	            dbl = !dbl;
