40	     * {@code '/api/owners/<id>'}, built from the owner's assigned id. Returns {@code null}
41	     * when the owner has no id yet, so the field is omitted from the response.
42	     */
43	    default String toSelfLink(Owner owner) {
44	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
45	    }
46	
47	    /**
48	     * Derive the owner's read-only {@code telephoneDisplay}: the stored E.164 {@code telephone}
49	     * formatted for humans (country code, a space, then the national digits grouped in threes),
50	     * e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}. Returns {@code null} when the
51	     * owner has no telephone, so the field is omitted from the response.
52	     */
53	    default String toTelephoneDisplay(Owner owner) {
