59	     * the owner's {@code registrationDate} (see {@link Owner#getAgeBand()}). Returns {@code null}
60	     * when the owner has no {@code birthDate}, so the field is omitted from the response.
61	     */
62	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
63	        String ageBand = owner.getAgeBand();
64	        return ageBand == null ? null : OwnerDto.AgeBandEnum.fromValue(ageBand);
65	    }
66	
67	    /**
68	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
69	     * read-only {@code displayName} field returned on the Owner DTO.
70	     */
71	    default String toDisplayName(Owner owner) {
72	        return owner.getLastName() + ", " + owner.getFirstName();
73	    }
74	
75	    /**
76	     * Build the owner's initials as the upper-cased first letters of firstName and
77	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
78	     * read-only {@code initials} field returned on the Owner DTO.
79	     */
80	    default String toInitials(Owner owner) {
81	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
82	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
83	    }
