111	     * from the response.
112	     */
113	    default String toTimezone(Owner owner) {
114	        return RegionTimezones.timezoneOf(toLocality(owner));
115	    }
116	
117	    /**
118	     * Derive the owner's read-only {@code contactPreference}: {@code EMAIL} when the owner has an
119	     * email address, otherwise {@code PHONE}.
120	     */
