124	            : OwnerDto.ContactPreferenceEnum.PHONE;
125	    }
126	
127	    @Mapping(target = "idempotencyKey", ignore = true)
128	    Owner toOwner(OwnerDto ownerDto);
129	
130	    @Mapping(target = "id", ignore = true)
131	    @Mapping(target = "pets", ignore = true)
132	    @Mapping(target = "idempotencyKey", ignore = true)
133	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
134	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
135	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
136	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
137	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
138	    Owner toOwner(OwnerFieldsDto ownerDto);
139	
140	    /**
141	     * Compose an owner's canonical {@code address} from whichever address form the request supplied.
142	     * The structured form is preferred: when {@code addressLine1} is non-blank after normalization,
143	     * the result is the normalized {@code addressLine1}, with a single space and the normalized
144	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise it falls back
145	     * to the normalized flat {@code address}. Each part is normalized with {@link AddressNormalizer}
146	     * (trimmed and whitespace-collapsed, upper-cased, street-type abbreviations expanded), so the
147	     * stored address is in one canonical shape regardless of the form used. Returns {@code null} when
148	     * no address was supplied in either form.
149	     */
150	    default String composeAddress(OwnerFieldsDto ownerDto) {
151	        String line1 = AddressNormalizer.normalize(ownerDto.getAddressLine1());
152	        if (line1 != null) {
153	            String line2 = AddressNormalizer.normalize(ownerDto.getAddressLine2());
154	            return line2 == null ? line1 : line1 + " " + line2;
155	        }
156	        return AddressNormalizer.normalize(ownerDto.getAddress());
157	    }
158	
159	    /**
160	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
161	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
162	     * compared in one shape. Blank-after-normalization is rejected separately by
163	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
164	     * value needs.
165	     */
166	    @Named("normalizeAddress")
167	    default String normalizeAddress(String address) {
168	        return AddressNormalizer.normalize(address);
169	    }
170	
171	    /**
172	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
173	     * code and national digits) so it is stored and returned in one comparable form and
174	     * duplicates can be detected by comparing these values. Format validity is enforced
175	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
176	     * the transform the stored value needs.
177	     */
178	    @Named("normalizeTelephone")
179	    default String normalizeTelephone(String telephone) {
180	        return TelephoneNormalizer.toE164(telephone);
181	    }
182	
183	    /**
184	     * Normalize an email address by trimming surrounding whitespace and lower-casing
185	     * it so it is stored and returned in a canonical form. Syntactic validity is
186	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
187	     * the transform the stored value needs.
188	     */
189	    @Named("normalizeEmail")
190	    default String normalizeEmail(String email) {
191	        return email == null ? null : email.trim().toLowerCase();
192	    }
193	
194	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
195	
196	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
197	
198	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
199	        OwnerPageDto ownerPageDto = new OwnerPageDto();
200	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
201	        ownerPageDto.setPage(ownerPage.getNumber());
202	        ownerPageDto.setSize(ownerPage.getSize());
203	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
204	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
205	        return ownerPageDto;
206	    }
207	}
